//! Actual current local TypeScript oracle, generated by scripts/compaction-current-oracle.mjs.
use super::runtime_adapter::compaction_completion;
use super::*;
use crate::build_session_context;
use pi_core::{
    Message,
    session::{AgentMessage, SessionRecord},
};
use serde_json::{Value, json};

fn corpus() -> Value {
    serde_json::from_str(include_str!(
        "../../../tests/fixtures/compaction-current-oracle.json"
    ))
    .unwrap()
}

#[test]
fn current_oracle_preparation_matches_projected_turns_edits_and_repeated_compaction() {
    let fixture = corpus();
    let mut failures = Vec::new();
    for case in fixture["cases"].as_array().unwrap() {
        let records: Vec<SessionRecord> =
            serde_json::from_value(case["rustEntries"].clone()).unwrap();
        let settings = serde_json::from_value(case["settings"].clone()).unwrap();
        let actual = prepare_compaction(
            &records,
            settings,
            &Default::default(),
            &GenericCompactionPolicy,
        );
        let expected = &case["expected"];
        let selected = |value: &Value| {
            if value.is_null() {
                Value::Null
            } else {
                json!({
                    "firstKeptEntryId": value["firstKeptEntryId"],
                    "messagesToSummarize": value["messagesToSummarize"],
                    "turnPrefixMessages": value["turnPrefixMessages"],
                    "retainedTail": value["retainedTail"],
                    "isSplitTurn": value["isSplitTurn"],
                    "tokensBefore": value["tokensBefore"],
                    "previousSummary": value["previousSummary"],
                })
            }
        };
        let actual = actual.map_or(Value::Null, |value| {
            json!({
                "firstKeptEntryId": value.first_kept_entry_id,
                "messagesToSummarize": value.messages_to_summarize,
                "turnPrefixMessages": value.turn_prefix_messages,
                "retainedTail": value.retained_tail,
                "isSplitTurn": value.is_split_turn,
                "tokensBefore": value.tokens_before,
                "previousSummary": value.previous_summary,
            })
        });
        let expected = selected(expected);
        if actual != expected {
            failures.push(format!(
                "{}\nactual: {actual}\nexpected: {expected}",
                case["name"]
            ));
        }
        let context = build_session_context(&records, &Default::default());
        let estimate = estimate_session_context_tokens(&records, &context.messages);
        if estimate.tokens != case["estimate"]["tokens"].as_u64().unwrap() {
            failures.push(format!(
                "{} estimate: {estimate:?}; expected: {}",
                case["name"], case["estimate"]
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n\n"));
}

#[test]
fn current_oracle_serialization_preserves_joining_and_unicode_truncation() {
    let fixture = corpus();
    let messages =
        serde_json::from_value::<Vec<AgentMessage>>(fixture["serialization"]["messages"].clone())
            .unwrap();
    assert_eq!(
        serialize_conversation(&messages),
        fixture["serialization"]["expected"]
    );
    for case in fixture["tokens"].as_array().unwrap() {
        let message = serde_json::from_value(case["message"].clone()).unwrap();
        assert_eq!(
            estimate_tokens(&message),
            case["expected"].as_u64().unwrap()
        );
    }
}

#[test]
fn current_oracle_raw_usage_uses_order_not_timestamps() {
    let fixture = corpus();
    let messages: Vec<AgentMessage> =
        serde_json::from_value(fixture["contextUsage"]["messages"].clone()).unwrap();
    let usage = estimate_context_tokens(&messages);
    assert_eq!(
        usage.tokens,
        fixture["contextUsage"]["expected"]["tokens"]
            .as_u64()
            .unwrap()
    );
    assert_eq!(usage.last_usage_index, Some(1));
}

#[test]
fn current_oracle_summary_completion_joins_text_blocks_with_newlines() {
    let fixture = corpus();
    let mut response = fixture["tokens"][2]["message"].clone();
    response["content"] = json!([
        {"type":"text", "text":"summary one"},
        {"type":"thinking", "thinking":"not output"},
        {"type":"text", "text":"summary two"},
    ]);
    let response: AgentMessage = serde_json::from_value(response).unwrap();
    let Some(Message::Assistant(response)) = response.as_standard() else {
        panic!("expected assistant");
    };
    let completion = compaction_completion(Ok((**response).clone())).unwrap();
    assert_eq!(completion.text, "summary one\nsummary two");
}
